from math import gcd
from sympy import binomial

def check_n(n):
    if gcd(n, 6) != 1:
        return False

    # Range for a: ceil(n/3) <= a <= floor(n/2)
    import math
    a_min = math.ceil(n / 3)
    a_max = math.floor(n / 2)

    if a_min > a_max:
        # Should not happen for n >= 2
        return False 

    for a in range(int(a_min), int(a_max) + 1):
        m = n - 2 * a

        # m must be positive since n is odd and a <= n/2
        if m <= 0:
            # This should be impossible given the range of a
            continue 

        # Required condition: binomial(a-1, m-1) must be a multiple of m
        try:
            coeff = binomial(a - 1, m - 1)
            if coeff % m != 0:
                # Condition failed
                return False
        except ValueError:
            # Handles cases where indices are invalid, which should not occur if logic is correct
            return False

    return True

# Check all n such that 71 <= n < 200 and gcd(n, 6)=1
solutions = []
for n in range(71, 200):
    if gcd(n, 6) == 1:
        if check_n(n):
            solutions.append(n)

print(f"Total solutions found: {len(solutions)}")
